1	package security
2	
3	import (
4		"fmt"
5		"strings"
6		"testing"
7	
8		"github.com/charmbracelet/x/ansi"
9	
10		"github.com/anthnel/devdesk/internal/scan"
11		"github.com/anthnel/devdesk/internal/ui/testutil"
12		"github.com/anthnel/devdesk/internal/ui/theme"
13	)
14	
15	// DEVDESK-750 (step 4): the finding detail is readable. Nothing overflows the
16	// viewport, the title is one line, the Message is capped, the fix status and the
17	// remediation come before the facts, and no empty line is left behind by a
18	// section that has nothing to say.
19	
20	// detailsTarget is the directory the fixtures were scanned from. It is only a
21	// string: a directory result is never read from disk by the detail.
22	const detailsTarget = "/work/repo"
23	
24	// detailsSizes are the three terminals of the plan's measured layout table: the
25	// width the router hands the view and the height of its viewport.
26	var detailsSizes = []struct{ width, height int }{{80, 12}, {120, 28}, {175, 38}}
27	
28	// textWidth is what a line of text may span: the viewport is two cells narrower
29	// than the view, and the padding takes one cell on each side.
30	func textWidth(width int) int { return width - 4 }
31	
32	// tabOf is the tab that lists f.
33	func tabOf(t *testing.T, f scan.Finding) int {
34		t.Helper()
35		for tab, category := range tabCategory {
36			if category == scan.Categorize(f) {
37				return tab
38			}
39		}
40		t.Fatalf("no tab lists %s", f.ID)
41		return -1
42	}
43	
44	// openDetail opens the detail of f the way a user does: a result holding f, the
45	// tab that lists it, enter.
46	func openDetail(t *testing.T, f scan.Finding, width, height int) Model {
47		t.Helper()
48		result := &scan.Result{Target: detailsTarget, TargetType: scan.TargetDirectory, Findings: []scan.Finding{f}}
49		m := feed(t, NewWithPreloadedResult(testConfig(), nil, result), testutil.Resize(width, height))
50		m.switchTab(tabOf(t, f))
51		m = feed(t, m, testutil.Key("enter"))
52		if m.state != StateDetails || m.selectedFinding == nil {
53			t.Fatalf("enter on %s did not open its details (state %v)", f.ID, m.state)
54		}
55		return m
56	}
57	
58	// plainLines is the built content without its styling, one entry per line.
59	func plainLines(m Model) []string { return strings.Split(ansi.Strip(m.buildDetailsContent()), "\n") }
60	
61	// sectionAfter is the lines under a heading, up to the next blank line.
62	func sectionAfter(lines []string, heading string) []string {
63		for i, line := range lines {
64			if strings.TrimSpace(line) != heading {
65				continue
66			}
67			var out []string
68			for _, next := range lines[i+1:] {
69				if strings.TrimSpace(next) == "" {
70					break
71				}
72				out = append(out, strings.TrimSpace(next))
73			}
74			return out
75		}
76		return nil
77	}
78	
79	func indexOfLine(lines []string, contains string) int {
80		for i, line := range lines {
81			if strings.Contains(line, contains) {
82				return i
83			}
84		}
85		return -1
86	}
87	
88	// ── Fixtures ─────────────────────────────────────────────────────────────────
89	
90	const renderFirstLine = "Error: lstat " + detailsTarget + "/k8s/base: no such file or directory"
91	
92	// renderFailureFixture is built like scan.renderFailure builds one: the title
93	// carries the first line of the renderer's stderr, the Message all of it, and
94	// the paths are absolute, under the scanned directory or under the container
95	// mount.
96	func renderFailureFixture() scan.Finding {
97		lines := []string{renderFirstLine}
98		for i := 2; i <= 15; i++ {
99			root := detailsTarget
100			if i%2 == 0 {
101				root = "/scan"
102			}
103			lines = append(lines, fmt.Sprintf("line %02d: open %s/k8s/overlays/prod/p%02d.yaml: denied", i, root, i))
104		}
105		return scan.Finding{
106			ID: scan.K8sRenderID, Title: "Overlay does not build: " + renderFirstLine,
107			Description: "The directory could not be rendered, so none of its resources were validated.",
108			Message:     strings.Join(lines, "\n"),
109			Resolution:  "Build it locally with kustomize build (or kubectl kustomize) and fix what it reports.",
110			Severity:    scan.SeverityHigh, Source: scan.SourceKustomize, File: "k8s/overlays/prod", IaCType: "kustomize",
111		}
112	}
113	
114	func ksv0001(message string) scan.Finding {
115		return scan.Finding{
116			ID: "KSV-0001", Title: "Process can elevate its own privileges", Severity: scan.SeverityHigh,
117			Description: "A program inside the container can elevate its own privileges and run as root.",
118			Message:     message, Source: scan.SourceTrivyMisconfig, File: "deploy.yaml", Line: 10, IaCType: "kubernetes",
119			References: []string{"https://avd.aquasec.com/misconfig/ksv001"},
120		}
121	}
122	
123	func cveWith(ecosystem, fixCommand string) scan.Finding {
124		return scan.Finding{
125			ID: "CVE-2026-1111", Title: "A flaw in a dependency", Severity: scan.SeverityHigh, Source: scan.SourceTrivy,
126			PkgName: "golang.org/x/net", Ecosystem: ecosystem, Version: "0.1.0", FixedIn: "0.7.0",
127			FixCommand: fixCommand, References: []string{"https://nvd.example/CVE-2026-1111"},
128		}
129	}
130	
131	func longSecret() scan.Finding {
132		return scan.Finding{
133			ID: "generic-api-key", Title: "A key in the tree", Severity: scan.SeverityHigh, Source: scan.SourceGitleaks,
134			File: "config/prod.env", Line: 12, Match: strings.Repeat("A", 300),
135		}
136	}
137	
138	func longCVE() scan.Finding {
139		f := cveWith("gomod", "go get "+strings.Repeat("p", 200))
140		f.PkgName = strings.Repeat("q", 200)
141		f.Version = strings.Repeat("1", 200)
142		f.FixedIn = strings.Repeat("2", 200)
143		return f
144	}
145	
146	func minimalFinding() scan.Finding {
147		return scan.Finding{ID: "X-1", Title: "Only a title", Severity: scan.SeverityLow}
148	}
149	
150	// detailsFixtures are the findings every layout assertion runs over.
151	func detailsFixtures() map[string]scan.Finding {
152		return map[string]scan.Finding{
153			"render failure": renderFailureFixture(),
154			"long message":   ksv0001(strings.Repeat("alpha beta gamma ", 60)),
155			"known cve":      cveWith("gomod", "go get golang.org/x/net@v0.7.0"),
156			"unknown cve":    func() scan.Finding { f := cveWith("conda", "Update foo to 1.2"); f.PkgName = "foo"; return f }(),
157			"long secret":    longSecret(),
158			"long cve":       longCVE(),
159			"minimal":        minimalFinding(),
160		}
161	}
162	
163	// ── Nothing overflows (AC1) ──────────────────────────────────────────────────
164	
165	func requireWithin(t *testing.T, label string, lines []string, limit int) {
166		t.Helper()
167		for i, line := range lines {
168			if got := ansi.StringWidth(line); got > limit {
169				t.Errorf("%s: line %d spans %d cells, limit %d: %q", label, i, got, limit, ansi.Strip(line))
170				return
171			}
172		}
173	}
174	
175	func TestNoLineOfTheDetailOverflowsTheViewport(t *testing.T) {
176		for name, f := range detailsFixtures() {
177			for _, size := range detailsSizes {
178				t.Run(fmt.Sprintf("%s/%d", name, size.width), func(t *testing.T) {
179					m := openDetail(t, f, size.width, size.height)
180					limit := size.width - 2
181					requireWithin(t, "buildDetailsContent", strings.Split(m.buildDetailsContent(), "\n"), limit)
182					requireWithin(t, "viewport", strings.Split(m.renderDetailsView(), "\n"), limit)
183				})
184			}
185		}
186	}
187	
188	// Under 46 columns the old floor of 40 cells for the text overflowed.
189	func TestNoLineOfTheDetailOverflowsANarrowTerminal(t *testing.T) {
190		for name, f := range detailsFixtures() {
191			for _, width := range []int{30, 40, 45} {
192				t.Run(fmt.Sprintf("%s/%d", name, width), func(t *testing.T) {
193					m := openDetail(t, f, width, 12)
194					requireWithin(t, "buildDetailsContent", strings.Split(m.buildDetailsContent(), "\n"), width-2)
195					requireWithin(t, "viewport", strings.Split(m.renderDetailsView(), "\n"), width-2)
196				})
197			}
198		}
199	}
200	
201	// The viewport has two border cells to give back, from the enter key and from a
202	// resize, whichever state the view is in when the terminal changes.
203	func TestTheDetailsViewportIsTwoCellsNarrowerThanTheView(t *testing.T) {
204		for _, size := range detailsSizes {
205			m := openDetail(t, longCVE(), size.width, size.height)
206			if got, want := m.detailsViewport.Width(), size.width-2; got != want {
207				t.Errorf("after enter at %d: viewport width = %d, want %d", size.width, got, want)
208			}
209			if got := m.detailsViewport.Height(); got != size.height {
210				t.Errorf("after enter at %d: viewport height = %d, want %d", size.width, got, size.height)
211			}
212		}
213	
