434	// requireTidy fails on a blank line at either end of the text (the padding's own
435	// blank line is allowed once at each end) and on two blank lines in a row.
436	func requireTidy(t *testing.T, label, content string) {
437		t.Helper()
438		blank := func(s string) bool { return strings.TrimSpace(s) == "" }
439		lines := strings.Split(ansi.Strip(content), "\n")
440		if len(lines) > 0 && blank(lines[0]) {
441			lines = lines[1:]
442		}
443		if len(lines) > 0 && blank(lines[len(lines)-1]) {
444			lines = lines[:len(lines)-1]
445		}
446		if len(lines) == 0 {
447			t.Errorf("%s: the content is empty", label)
448			return
449		}
450		if blank(lines[0]) {
451			t.Errorf("%s: the text starts with a blank line", label)
452		}
453		if blank(lines[len(lines)-1]) {
454			t.Errorf("%s: the text ends with a blank line", label)
455		}
456		for i := 1; i < len(lines); i++ {
457			if blank(lines[i]) && blank(lines[i-1]) {
458				t.Errorf("%s: two blank lines in a row at text line %d:\n%s", label, i, strings.Join(lines, "\n"))
459				return
460			}
461		}
462	}
