17	// handleDetailsState processes input in details state
18	func (m Model) handleDetailsState(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
19		switch msg.String() {
20		// backspace was an alias of esc, and the only one in the application.
21		case "esc":
22			m.state = StateResults
23			return m, nil
24		case keymap.Web:
25			return m.handleDetailsOpenReference()
26		case "up":
27			m.detailsViewport.ScrollUp(1)
28		case "down":
29			m.detailsViewport.ScrollDown(1)
30		case "pgup":
31			m.detailsViewport.HalfPageUp()
32		case "pgdown":
33			m.detailsViewport.HalfPageDown()
34		case "home":
35			m.detailsViewport.GotoTop()
36		case "end":
37			m.detailsViewport.GotoBottom()
38		}
39		return m, nil
40	}
