60	// buildDetailsContent builds the full scrollable content for the details view.
61	func (m Model) buildDetailsContent() string {
62		if m.selectedFinding == nil {
63			return theme.Bg("No finding selected")
64		}
65	
66		f := *m.selectedFinding
67		var b strings.Builder
68	
69		// Available width inside padding (1 left + 1 right)
70		contentWidth := max(m.width-6, 40)
71		textStyle := lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorText)
72		wrapStyle := textStyle.Width(contentWidth)
73	
74		// Header: severity + ID on same line with proper background
75		severityStyle := m.getSeverityStyle(f.Severity)
76		b.WriteString(severityStyle.Render(string(f.Severity)) + theme.Bg(" ") + theme.TitleStyle.Render(f.ID) + "\n\n")
77	
78		// Title with wrapping
79		b.WriteString(theme.SubTitleStyle.Render("Title:") + "\n")
80		b.WriteString(wrapStyle.Render(f.Title) + "\n\n")
81	
82		// Description with wrapping
83		if f.Description != "" {
84			b.WriteString(theme.SubTitleStyle.Render("Description:") + "\n")
85			b.WriteString(wrapStyle.Render(f.Description) + "\n\n")
86		}
87	
88		b.WriteString(theme.SubTitleStyle.Render("Source: ") + textStyle.Render(f.Source) + "\n")
89		if f.IaCType != "" {
90			b.WriteString(theme.SubTitleStyle.Render("Type: ") + textStyle.Render(f.IaCType) + "\n")
91		}
92	
93		if label := pssLabel(f); label != "" {
94			b.WriteString(theme.SubTitleStyle.Render("Pod Security: ") + textStyle.Render(label) + "\n")
95		}
96	
97		// File path with wrapping (can be long)
98		if f.File != "" {
99			b.WriteString(theme.SubTitleStyle.Render("File: ") + textStyle.Width(contentWidth-6).Render(f.File) + "\n")
100		}
101	
102		if f.Line > 0 {
103			b.WriteString(theme.SubTitleStyle.Render("Line: ") + textStyle.Render(fmt.Sprintf("%d", f.Line)) + "\n")
104		}
105	
106		if f.PkgName != "" {
107			b.WriteString(theme.SubTitleStyle.Render("Package: ") + textStyle.Render(f.PkgName) + "\n")
108			if kind := packageKind(f.Class); kind != "" {
109				b.WriteString(theme.SubTitleStyle.Render("Kind: ") + textStyle.Render(kind) + "\n")
110			}
111			if f.Version != "" {
112				b.WriteString(theme.SubTitleStyle.Render("Version: ") + textStyle.Render(f.Version) + "\n")
113			}
114			if f.FixedIn != "" {
115				b.WriteString(theme.SubTitleStyle.Render("Fixed In: ") + theme.StatusOKStyle.Render(f.FixedIn) + "\n")
116			}
117		}
118	
119		if f.Match != "" {
120			b.WriteString(theme.SubTitleStyle.Render("Match: ") + textStyle.Render(f.Match) + "\n")
121		}
122	
123		// The offending line of a CI finding, wrapped: it is a shell command and
124		// can be long. It is the only thing plumber says about *where inside a job*
125		// a control fired — the File above names the `include:` entry that brought
126		// the job in, which is the include responsible rather than the fault.
127		if f.ScriptLine != "" {
128			b.WriteString(theme.SubTitleStyle.Render("Script:") + "\n")
129			b.WriteString(wrapStyle.Render(f.ScriptLine) + "\n")
130		}
131	
132		// Remediation section
133		if f.Resolution != "" || f.FixCommand != "" {
134			b.WriteString("\n")
135			b.WriteString(theme.SubTitleStyle.Render("Remediation:") + "\n")
136			if f.Resolution != "" {
137				b.WriteString(wrapStyle.Render(f.Resolution) + "\n")
138			}
139			if f.FixCommand != "" {
140				b.WriteString(theme.DimStyle.Render("Run: ") + textStyle.Render(f.FixCommand) + "\n")
141			}
142		}
143	
144		// References section
145		if len(f.References) > 0 {
146			b.WriteString("\n")
147			b.WriteString(theme.SubTitleStyle.Render("References:") + "\n")
148			for _, ref := range f.References {
149				b.WriteString(textStyle.Width(contentWidth-2).Render("  "+ref) + "\n")
150			}
151		}
152	
153		return lipgloss.NewStyle().
154			Padding(1).
155			Background(theme.ColorBackground).
156			Render(b.String())
157	}
