21	func TestTheFooterSaysWhichLinesOfALongDetailAreOnScreen(t *testing.T) {
22		m := openDetail(t, renderFailureFixture(), 80, 12)
23		total := m.detailsViewport.TotalLineCount()
24		if total <= 12 {
25			t.Fatalf("the fixture has %d lines, it must overflow 12", total)
26		}
27	
28		steps := []struct {
29			name string
30			keys []string
31			want string
32		}{
33			{"on opening", nil, fmt.Sprintf("Lines 1-12 of %d", total)},
34			{"one line down", []string{"down"}, fmt.Sprintf("Lines 2-13 of %d", total)},
35			{"at the end", []string{"end"}, fmt.Sprintf("Lines %d-%d of %d", total-11, total, total)},
36			{"back at the top", []string{"end", "home"}, fmt.Sprintf("Lines 1-12 of %d", total)},
37		}
38		for _, step := range steps {
39			t.Run(step.name, func(t *testing.T) {
40				got := footerText(feed(t, m, testutil.Keys(step.keys...)...), 80)
41				if !strings.Contains(got, step.want) {
42					t.Errorf("footer = %q, want it to contain %q", got, step.want)
43				}
44			})
45		}
46	}
