31	// fileFixtures are three misconfigurations of one file apiece: a relative path,
32	// one under the container mount, and an absolute one under HOME that is longer
33	// than the column may be.
34	func fileFixtures(home string) []scan.Finding {
35		deep := filepath.Join(home, "projects", "an-application", "deploy", "kubernetes", "overlays", "production", "manifest-file.yaml")
36		mk := func(id, file string) scan.Finding {
37			return scan.Finding{ID: id, Title: "A misconfiguration", Severity: scan.SeverityHigh,
38				Source: scan.SourceTrivyMisconfig, File: file, IaCType: "kubernetes"}
39		}
40		return []scan.Finding{
41			mk("KSV-0001", "Dockerfile"),
42			mk("KSV-0003", "/scan/k8s/base/deployment.yaml"),
43			mk("KSV-0009", deep),
44		}
45	}
