70		}
71		if c.Sizing != datatable.SizingContent || c.MinWidth != 16 || c.MaxWidth != 40 || !c.Optional || !c.TruncateHead {
72			t.Errorf("File = %+v, want SizingContent, 16..40, Optional, TruncateHead", c)
73		}
74		if c.Less != nil || c.Search != nil {
75			t.Error("File sorts or searches: the Title search already matches the file, and a second way to ask is noise")
76		}
77	}
