129	// Rule 122: plain text, measured before it is coloured. And the path a user
130	// reads is the one in the project, not the one inside the scanner's container.
131	func TestTheFileCellsArePlainAndShort(t *testing.T) {
132		m := fileModel(t, 175, TabMisconfig)
133		at := fileColumnIndex(t)
134	
135		cells := map[string]string{}
136		for _, row := range m.findingsTable.Table().Rows() {
137			if len(row) <= at {
