141				t.Errorf("the File cell of %s carries an escape sequence: %q", row[1], row[at])
142			}
143			cells[row[1]] = row[at]
144		}
145	
146		if got := cells["KSV-0001"]; got != "Dockerfile" {
147			t.Errorf("relative path = %q", got)
148		}
149		if got := cells["KSV-0003"]; got != "k8s/base/deployment.yaml" {
150			t.Errorf("a path under the container mount = %q, want it without /scan/", got)
151		}
152		if got := cells["KSV-0009"]; !strings.HasPrefix(got, "~/projects/") {
153			t.Errorf("a path under HOME = %q, want it folded to ~/", got)
154		}
155	}
