158	// two findings apart.
159	func TestALongFilePathKeepsItsTail(t *testing.T) {
160		m := fileModel(t, 175, TabMisconfig)
161	
162		var line string
163		for _, l := range strings.Split(ansi.Strip(m.findingsTable.View()), "\n") {
