func (m Model) buildDetailsContent() string {
	if m.selectedFinding == nil {
		return theme.Bg("No finding selected")
	}

	f := *m.selectedFinding
	t := detailsText{width: m.detailsTextWidth()}
	target := m.scanTarget()

	var sections []string
	for _, section := range [][]string{
